import { promises as fs } from "node:fs";
import os from "node:os";
import path from "node:path";

import { afterAll, beforeAll, beforeEach, describe, expect, it } from "vitest";

let tmpDir: string;
let originalCwd: string;
let readFileTool: typeof import("@/lib/agent/tools/read-file").readFileTool;

const MAX_READ_BYTES = 64 * 1024;

beforeAll(async () => {
  originalCwd = process.cwd();
  tmpDir = await fs.mkdtemp(path.join(os.tmpdir(), "codify-read-file-"));
  process.chdir(tmpDir);
  const module = await import("@/lib/agent/tools/read-file");
  readFileTool = module.readFileTool;
});

afterAll(async () => {
  process.chdir(originalCwd);
  await fs.rm(tmpDir, { force: true, recursive: true });
});

beforeEach(async () => {
  // Clean up any files created during tests
  const files = await fs.readdir(tmpDir);
  for (const file of files) {
    const filePath = path.join(tmpDir, file);
    const stat = await fs.stat(filePath);
    if (stat.isFile()) {
      await fs.unlink(filePath);
    } else if (stat.isDirectory()) {
      await fs.rm(filePath, { recursive: true });
    }
  }
});

describe("readFileTool", () => {
  describe("execute", () => {
    it("reads a simple text file successfully", async () => {
      const content = "Hello, World!";
      await fs.writeFile(path.join(tmpDir, "test.txt"), content, "utf-8");

      const result = await readFileTool.execute({ path: "test.txt" });

      expect(result).toEqual({
        bytes: Buffer.byteLength(content),
        content: content,
        path: "test.txt",
        truncated: false,
      });
    });

    it("reads a file from a subdirectory", async () => {
      const content = "Nested content";
      await fs.mkdir(path.join(tmpDir, "subdir"), { recursive: true });
      await fs.writeFile(path.join(tmpDir, "subdir", "nested.txt"), content, "utf-8");

      const result = await readFileTool.execute({ path: "subdir/nested.txt" });

      expect(result).toEqual({
        bytes: Buffer.byteLength(content),
        content: content,
        path: "subdir/nested.txt",
        truncated: false,
      });
    });

    it("reads an empty file successfully", async () => {
      await fs.writeFile(path.join(tmpDir, "empty.txt"), "", "utf-8");

      const result = await readFileTool.execute({ path: "empty.txt" });

      expect(result).toEqual({
        bytes: 0,
        content: "",
        path: "empty.txt",
        truncated: false,
      });
    });

    it("reads a file with UTF-8 characters", async () => {
      const content = "Hello 世界 🌍 Привет";
      await fs.writeFile(path.join(tmpDir, "unicode.txt"), content, "utf-8");

      const result = await readFileTool.execute({ path: "unicode.txt" });

      expect(result).toEqual({
        bytes: Buffer.byteLength(content),
        content: content,
        path: "unicode.txt",
        truncated: false,
      });
    });

    it("truncates files larger than 64 KiB", async () => {
      // Create a file with exactly MAX_READ_BYTES + 100 bytes
      const largeContent = "a".repeat(MAX_READ_BYTES + 100);
      await fs.writeFile(path.join(tmpDir, "large.txt"), largeContent, "utf-8");

      const result = await readFileTool.execute({ path: "large.txt" });

      expect(result.bytes).toBe(MAX_READ_BYTES + 100);
      expect(result.content).toBe("a".repeat(MAX_READ_BYTES));
      expect(result.path).toBe("large.txt");
      expect(result.truncated).toBe(true);
      expect(result.content.length).toBe(MAX_READ_BYTES);
    });

    it("does not truncate a file exactly at the limit", async () => {
      // Create a file with exactly MAX_READ_BYTES
      const content = "b".repeat(MAX_READ_BYTES);
      await fs.writeFile(path.join(tmpDir, "exact.txt"), content, "utf-8");

      const result = await readFileTool.execute({ path: "exact.txt" });

      expect(result).toEqual({
        bytes: MAX_READ_BYTES,
        content: content,
        path: "exact.txt",
        truncated: false,
      });
    });

    it("truncates a file one byte over the limit", async () => {
      // Create a file with MAX_READ_BYTES + 1 byte
      const content = "c".repeat(MAX_READ_BYTES + 1);
      await fs.writeFile(path.join(tmpDir, "over-limit.txt"), content, "utf-8");

      const result = await readFileTool.execute({ path: "over-limit.txt" });

      expect(result.bytes).toBe(MAX_READ_BYTES + 1);
      expect(result.content).toBe("c".repeat(MAX_READ_BYTES));
      expect(result.path).toBe("over-limit.txt");
      expect(result.truncated).toBe(true);
    });

    it("throws an error when the file does not exist", async () => {
      await expect(
        readFileTool.execute({ path: "nonexistent.txt" })
      ).rejects.toThrow();
    });

    it("throws an error when trying to read a directory", async () => {
      await fs.mkdir(path.join(tmpDir, "a-directory"), { recursive: true });

      await expect(
        readFileTool.execute({ path: "a-directory" })
      ).rejects.toThrow();
    });

    it("throws an error when trying to escape the project directory", async () => {
      // Create a file outside the project directory
      const outsideDir = path.join(os.tmpdir(), "outside-project");
      await fs.mkdir(outsideDir, { recursive: true });
      await fs.writeFile(path.join(outsideDir, "secret.txt"), "secret", "utf-8");

      try {
        // Try to access it using relative path traversal
        await expect(
          readFileTool.execute({ path: "../outside-project/secret.txt" })
        ).rejects.toThrow(/escapes the project directory/);
      } finally {
        await fs.rm(outsideDir, { force: true, recursive: true });
      }
    });

    it("handles paths with leading slash as relative paths", async () => {
      const content = "Leading slash test";
      await fs.writeFile(path.join(tmpDir, "leading.txt"), content, "utf-8");

      const result = await readFileTool.execute({ path: "/leading.txt" });

      expect(result).toEqual({
        bytes: Buffer.byteLength(content),
        content: content,
        path: "/leading.txt",
        truncated: false,
      });
    });

    it("handles paths with ./ prefix", async () => {
      const content = "Dot slash test";
      await fs.writeFile(path.join(tmpDir, "dot.txt"), content, "utf-8");

      const result = await readFileTool.execute({ path: "./dot.txt" });

      expect(result).toEqual({
        bytes: Buffer.byteLength(content),
        content: content,
        path: "./dot.txt",
        truncated: false,
      });
    });

    it("reads files with special characters in the name", async () => {
      const content = "Special chars";
      const filename = "file-with-special_chars.test.txt";
      await fs.writeFile(path.join(tmpDir, filename), content, "utf-8");

      const result = await readFileTool.execute({ path: filename });

      expect(result).toEqual({
        bytes: Buffer.byteLength(content),
        content: content,
        path: filename,
        truncated: false,
      });
    });

    it("reads a binary-looking file as UTF-8", async () => {
      // Write some bytes that could be binary
      const buffer = Buffer.from([0x48, 0x65, 0x6c, 0x6c, 0x6f]); // "Hello"
      await fs.writeFile(path.join(tmpDir, "binary.bin"), buffer);

      const result = await readFileTool.execute({ path: "binary.bin" });

      expect(result).toEqual({
        bytes: 5,
        content: "Hello",
        path: "binary.bin",
        truncated: false,
      });
    });
  });

  describe("inputSchema", () => {
    it("validates a correct path", () => {
      const result = readFileTool.inputSchema.safeParse({
        path: "some/valid/path.txt",
      });

      expect(result.success).toBe(true);
    });

    it("rejects input without a path", () => {
      const result = readFileTool.inputSchema.safeParse({});

      expect(result.success).toBe(false);
    });

    it("rejects input with non-string path", () => {
      const result = readFileTool.inputSchema.safeParse({
        path: 123,
      });

      expect(result.success).toBe(false);
    });

    it("rejects input with null path", () => {
      const result = readFileTool.inputSchema.safeParse({
        path: null,
      });

      expect(result.success).toBe(false);
    });
  });

  describe("metadata", () => {
    it("has a description", () => {
      expect(readFileTool.description).toBeDefined();
      expect(typeof readFileTool.description).toBe("string");
      expect(readFileTool.description.length).toBeGreaterThan(0);
    });

    it("description mentions truncation behavior", () => {
      expect(readFileTool.description).toMatch(/truncate/i);
      expect(readFileTool.description).toMatch(/64.*KiB/i);
    });

    it("description mentions relative paths", () => {
      expect(readFileTool.description).toMatch(/relative.*project root/i);
    });
  });
});

